    static func solo(_ kid: Kid, _ room: String) -> [String] {
        if kid.toddler {
            switch room {
            case "kitchen": return ["مويه! 💧", "أكل! 🍽️", "تفاحة! 🍎", "موزة! 🍌"]
            case "bath": return ["أسنان! 🪥", "فقاعات! 🫧", "بطة! 🦆", "مويه! 💦"]
            case "bedroom": return ["نوم! 😴", "ملابس! 👕", "ألوان! 🖍️", "بالون! 🎈"]
            default: return ["ألعاب! 🧸", "سلام! 👋", "كورة! ⚽", "سيارة! 🚗"]
            }
        }
        switch room {
        case "kitchen": return ["ريحة الأكل حلوة! 😋", "بساعد في ترتيب السفرة 🍽️", "الزبالة لازم تطلع 🗑️", "الصحون مكانها المغسلة 🚰", "نرتّب المقاضي في الدولاب 🥫"]
        case "bath": return ["وقت الأسنان! 🪥", "المغسلة لازم تكون نظيفة 🚿", "الجوارب في السلة 🧦", "نغسل يدينا قبل الأكل 🧼"]
        case "bedroom": return ["سريري لازم يترتب 🛏️", "وين شنطتي؟ 🎒", "يلا نخلّص الواجب 📝", "الكتب مكانها المكتب 📘", "الملابس في الدولاب 👚"]
        default: return ["وين ألعابي؟ 🧸", "يلا تحدي العيلة! 🤝", "الحمد لله على كل شي 🤲", "الجزم مكانها الرف 👟", "مين يلعب معي؟ ⚽"]
        }
    }
